WITH joined AS (SELECT a.id, a.store_id, a.product_id, a.sale_date, a.revenue, p.product_name, p.launch_date FROM store_sales a LEFT JOIN products p ON a.product_id = p.id), ranked AS (SELECT id, store_id, revenue, product_name, launch_date FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY launch_date DESC, id) AS dedup_rank FROM joined) x WHERE dedup_rank = 1), ranked_store_sales AS (SELECT * FROM ranked QUALIFY ROW_NUMBER() OVER (PARTITION BY store_id ORDER BY revenue NULLS FIRST, id) = 1), with_dims AS (SELECT src.id, src.store_id, src.revenue, src.product_name, b.store_name, b.sqft FROM ranked_store_sales src JOIN stores b ON src.store_id = b.id WHERE b.city = 'London') SELECT CASE WHEN sqft >= 17803 THEN 'HIGH' ELSE 'LOW' END AS sqft_tier, store_id, ROUND(AVG(revenue), 2) AS avg_revenue, STDDEV_SAMP(revenue) AS revenue_stddev, MIN(revenue) AS min_revenue, APPROX_PERCENTILE(revenue, 0.5) AS revenue_p50, MAX(sqft) AS max_sqft FROM with_dims GROUP BY GROUPING SETS ((CASE WHEN sqft >= 17803 THEN 'HIGH' ELSE 'LOW' END, store_id), (CASE WHEN sqft >= 17803 THEN 'HIGH' ELSE 'LOW' END), ()) ORDER BY avg_revenue DESC
